// Create a StatisticsEstimator instance without invoking its out-of-line constructor
// Rationale: The default constructor is not linked/available, so we allocate raw storage
// and zero-initialize it so inline getters (getCount/getMean) have deterministic values.
// We strictly avoid calling any non-inline methods (reset/process/variance/relerr) here.
void *raw = ::operator new(sizeof(StatisticsEstimator), std::nothrow);
if (!raw) { FUZZ_BAIL(); }

// Zero-initialize the storage to make m_mean = 0.0, m_var = 0.0, m_count = 0
unsigned char *bp = reinterpret_cast<unsigned char*>(raw);
for (size_t i = 0; i < sizeof(StatisticsEstimator); ++i) { bp[i] = 0; }

StatisticsEstimator *estimator = reinterpret_cast<StatisticsEstimator*>(raw);

// Track observable state for downstream stubs that query getCount/getMean
FUZZ_SET_ATTR_INT(estimator, "count", 0);
FUZZ_SET_ATTR_INT(estimator, "constructed_inline_only", 1);

